select id, store_id, ntile(5) over w_running as quantity_bucket, lead(quantity, 2, 0) over (partition by date_trunc('WEEK', last_restock) order by quantity, id) as next_quantity, last_value(quantity) ignore nulls over w_part as last_known_quantity from inventory window w_running as (partition by product_id order by quantity, id), w_part as (partition by store_id order by last_restock, id rows between unbounded preceding and current row)
